(()=>{'use strict';const P=window.ComboPricing,store=window.HolidayStore,records=window.TEATR_CATALOG.combo.programs,programs=Object.values(window.TEATR_CATALOG).flatMap(c=>c.programs),find=id=>programs.find(p=>p.id===id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let period=0,guests=10;
const ticket=label=>`<span class="ticket-size" aria-hidden="true">${label}</span><span class="ticket-label">${label}</span>`;
function select(name,label,list,value){return `<label class="bundle-field"><span>${label}</span><select name="${name}">${list.map(id=>`<option value="${id}" ${id===value?'selected':''}>${esc(find(id).title)}</option>`).join('')}</select></label>`}
function focus(id){const form=document.querySelector(`[data-bundle="${id}"]`);if(form){form.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});form.querySelector('select').focus({preventScroll:true})}}
function render(grid){grid.classList.add('combo-grid');const requested=new URL(location.href).searchParams.get('program'),saved=store.read().options?.[requested]?.combo;if(saved){period=saved.period;guests=saved.guests}
 grid.innerHTML=`<div class="bundle-toolbar"><div><h2>Ваш праздник — ваше комбо</h2><p>Анимация или квест без доплаты. Любой МК по одной цене для выбранной группы.</p></div><label>Дата и время праздника<select id="bundle-period">${P.periods.map((p,i)=>`<option value="${i}" ${i===period?'selected':''}>${p}</option>`).join('')}</select></label><label>Участников мастер-класса<select id="bundle-guests">${[5,10,20,30,31].map(n=>`<option value="${n}" ${n===guests?'selected':''}>${n===31?'Более 30 — индивидуально':'До '+n+' человек'}</option>`).join('')}</select></label></div><div class="bundle-grid">${records.map((r,i)=>{const d=P.definitions[r.id],o=P.clean(store.read().options?.[r.id]?.combo);return `<form class="bundle-card" data-bundle="${r.id}" style="--order:${i}"><div class="bundle-photo"><img src="${r.image}" alt="${esc(r.title)}" ${i>2?'loading="lazy"':''}><span class="bundle-mark"><img src="assets/combo.svg?v=20261029-puzzle19" alt="">${r.id==='combo-mega'?'Три программы':'Две программы'}</span><button class="icon-button bundle-heart" type="button" data-favorite="${r.id}" aria-label="В избранное: ${esc(r.title)}" aria-pressed="false">${window.HolidayIcons.heart}</button></div><div class="bundle-copy"><h2>${esc(r.title)}</h2><p class="bundle-description">${esc(r.description)}</p><p class="bundle-duration"></p>${select('base','Анимация или квест',P.allowed.base,o.base)}${d.showChoice?select('show','Одно шоу на выбор',P.allowed.show,o.show):''}${d.quiz?select('quiz','Экранная программа',P.allowed.quiz,o.quiz):''}${d.workshop?select('workshop','Любой мастер-класс',P.allowed.workshop,o.workshop):''}<div class="bundle-price" role="status" aria-live="polite"></div><button type="submit" class="ribbon gold bundle-submit">${ticket('Добавить комбо')}</button><p class="bundle-feedback" role="status"></p></div></form>`}).join('')}</div><p class="bundle-footnote">Программы проходят последовательно. В МК включены материалы, инструменты и проведение. Бумажное шоу — 5 кг бумаги. Дорога рассчитывается отдельно, один раз за общий выезд команды. Точную стоимость и свободное время подтвердим после заявки.</p>`;
 const forms=[...grid.querySelectorAll('[data-bundle]')];function choices(form){return P.clean({...Object.fromEntries(new FormData(form)),period,guests})}
 function update(form){const id=form.dataset.bundle,q=P.quote(id,choices(form)),d=P.definitions[id];form.querySelector('.bundle-duration').textContent=`${q.minutes} минут · анимация или квест без доплаты`;
 const show=d.showChoice?q.items.find(p=>p.category==='show'):null;if(show)form.querySelector('.bundle-photo>img').src=show.image;
 form.querySelector('.bundle-price').innerHTML=q.price===null?'<strong>Рассчитаем для вас</strong><span>Для МК более 30 участников — индивидуальная стоимость</span>':`<span class="bundle-separate">По отдельности <s>${P.money(q.actual)}</s></span><strong>${P.money(q.price)}</strong><span class="bundle-saving">Выгода ${P.money(q.saving)}</span><small>${d.workshop?'За весь пакет · МК до '+guests+' участников':'За весь пакет'} · без дороги</small>`;
 const current=store.read(),selected=current.cart.includes(id),same=selected&&JSON.stringify(P.clean(current.options?.[id]?.combo))===JSON.stringify(choices(form));form.querySelector('.bundle-submit').innerHTML=ticket(same?'В моём празднике':selected?'Обновить комбо':q.price===null?'Добавить для расчёта':'Добавить комбо');}
 forms.forEach(form=>{form.addEventListener('change',()=>{update(form);form.querySelector('.bundle-feedback').textContent=''});form.addEventListener('submit',e=>{e.preventDefault();store.setCombo(form.dataset.bundle,choices(form));update(form);form.querySelector('.bundle-feedback').innerHTML='Комбо сохранено. <a href="my-holiday.html">Открыть мой праздник →</a>'});update(form)});
 grid.querySelector('#bundle-period').addEventListener('change',e=>{period=Number(e.target.value);forms.forEach(update)});grid.querySelector('#bundle-guests').addEventListener('change',e=>{guests=Number(e.target.value);forms.forEach(update)});window.HolidayUI.sync();
}
window.ComboCatalog={render,focus};})();
